    // AC: @skill-type-guard ac-2 - isSkill returns false for non-skill items
    it('should return false for items without _type: skill', () => {
      const agent = {
        _ulid: testUlid('AGSKIP'),
        id: 'test-agent',
        name: 'Test Agent',
        capabilities: [],
        tools: [],
